"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[898],{50898:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-dangerous-venus.png\\"\\n          title=\\"위험한 비너스\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"현대문학\\"\\n          publishedDate=\\"2017-06-30\\"\\n          isbn=\\"9788972758242\\"\\n          rating=4\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n수학과 뇌과학을 작품의 중심 소재로 가져왔다.  \\n과학적 지식을 미스터리 장르와 결합하는 것이 그의 작품 세계를 규정하는 가장 큰 특징인 것 같다.  \\n<br>\\n<mark>유산 상속</mark>이라는 고전 미스터리 클리셰를 내세워 독자의 주의를 분산시킨다.  \\n미스터리 장르에 익숙한 독자는 자연스럽게 ```누가 돈 때문에 사건을 일으켰는가```에 집중하게 된다.  \\n그러나 동기는 순수하면서도 광적인 지적 탐욕이었다.  \\n<br>\\n뇌과학과 생명 윤리에 대한 작가의 깊은 관심이 보인다.  "}')}}]);